codeExamples.java:
public class Main {
    public static void main(String[] args) {
        int age = 25;
        double height = 5.9;
        boolean isStudent = true;
        String name = "Alice";
        double convertedAge = (double) age;
        System.out.println(name + " | Type: int | Float Age: " + convertedAge);
    }
}

