codeExamples.cpp:
#include <iostream>
#include <string>
int main() {
    int age = 25;
    double height = 5.9;
    bool isStudent = true;
    std::string name = "Alice";
    double convertedAge = static_cast<double>(age);
    std::cout << name << " | Type: int | Float Age: " << convertedAge << std::endl;
    return 0;
}
